"""Versioned aggregate projections for the sealed D1/D2 information wave."""
import argparse,csv,json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from nfl_v2.shared_subgroups import sha,load,write

def run(public_root,leader_file):
 root=Path(public_root);leader_file=Path(leader_file);scores=load(root/'SCORES.json')
 with leader_file.open()as f:leaders=list(csv.DictReader(f))
 prior={}
 for r in leaders:
  if r['rank']=='1':prior.setdefault((r['target'],r['ranking_product']),r)
 full=[r for r in scores if r['week']=='ALL'and r['position']=='ALL'and r['fallback_view']=='ALL'];point=[];law=[];mean=[]
 for target in sorted({r['target']for r in full}):
  rows=[r for r in full if r['target']==target and r['population']=='primary'];metric='brier'if target=='anytime_td'else'mae';best=min(rows,key=lambda r:(r[metric],r['information_group'],r['policy_id'],r['product_id']));old=prior[target,'display_point'];oldval=float(old['ranking_loss'])
  if best['n']!=int(old['n']):raise ValueError('oldleader full supported population changed')
  point.append(dict(target=target,n=best['n'],information_group=best['information_group'],policy_id=best['policy_id'],product_id=best['product_id'],metric=metric,candidate_error=best[metric],same_policy_ordered_error=best['comparison']['comparator_error'],same_policy_ordered_error_delta=best['comparison']['absolute_error_delta'],prior_strongest_error=oldval,prior_strongest_procedure_id=old['procedure_id'],prior_strongest_history_regime=old['history_regime'],prior_strongest_product=old['product'],error_delta_vs_prior_strongest=best[metric]-oldval,relative_error_delta_vs_prior_strongest=(best[metric]-oldval)/oldval if oldval else None,source_record_id=best['record_id'],fallback_rows=best['fallback_rows'],forecast_rows=best['forecast_rows'],selection_status='exposed observed group/history/product minimum; not an earlier frozen routing policy',strongest_reference_uncertainty='paired-loss uncertainty retained only for samepolicyordered primary comparison inSCORES; no invented strongest-reference SE from aggregates'))
  laws=[r for r in rows if r['product_id']in('mean','event_probability')];lm='brier'if target=='anytime_td'else'CRPS';bestlaw=min(laws,key=lambda r:(r[lm],r['information_group'],r['policy_id']));oldlaw=prior[target,'forecast_law'];ov=float(oldlaw['ranking_loss']);law.append(dict(target=target,n=bestlaw['n'],information_group=bestlaw['information_group'],policy_id=bestlaw['policy_id'],metric=lm,candidate_error=bestlaw[lm],prior_strongest_error=ov,error_delta=bestlaw[lm]-ov,prior_procedure_id=oldlaw['procedure_id'],prior_history_regime=oldlaw['history_regime'],NLL=bestlaw['NLL'],infinite_NLL=bestlaw['infinite_NLL'],NLL_state='INFINITE'if bestlaw['infinite_NLL']else'FINITE',interval90_width=bestlaw['interval90_width'],interval90_coverage=bestlaw['interval90_coverage'],mean_zero_mass=bestlaw['mean_zero_mass'],source_record_id=bestlaw['record_id']))
  if target!='anytime_td':
   bm=min(laws,key=lambda r:(r['mse'],r['information_group'],r['policy_id']));om=prior[target,'intended_mean'];ov=float(om['ranking_loss']);mean.append(dict(target=target,n=bm['n'],information_group=bm['information_group'],policy_id=bm['policy_id'],metric='mse',candidate_error=bm['mse'],prior_strongest_error=ov,error_delta=bm['mse']-ov,rmse=bm['rmse'],bias=bm['bias'],prior_procedure_id=om['procedure_id'],prior_history_regime=om['history_regime'],source_record_id=bm['record_id']))
 for name,rs in [('OBSERVED_POINT_MINIMA.csv',point),('OBSERVED_PROPER_LAW_MINIMA.csv',law),('OBSERVED_GENUINE_MEAN_MINIMA.csv',mean)]:
  with(root/name).open('x',newline='')as f:
   w=csv.DictWriter(f,fieldnames=list(rs[0]));w.writeheader();w.writerows(rs)
 result=dict(version='v2-qualified-defense-aggregate-strong-control-projection-v1',source_score_sha256=sha(root/'SCORES.json'),source_protocol_sha256=sha(root/'FROZEN_PROTOCOL.json'),old_leader_artifact=leader_file.as_posix(),old_leader_sha256=sha(leader_file),point_rows=point,proper_law_rows=law,genuine_mean_rows=mean,all_policy_full_views=[{k:r.get(k)for k in('record_id','information_group','policy_id','history_regime','product_id','target','population','n','forecast_rows','fallback_rows','mae','mse','rmse','bias','brier','CRPS','NLL','infinite_NLL','interval90_width','interval90_coverage','mean_zero_mass','comparison')}for r in full],new_fits=0,new_forecasts=0,week8_outcomes_read=0,limits='Oldrankstablepreviousfullpopulationfamilyrepresentatives. Newminimaselectexposed2026results andarenotdeployableselection. Nativeunits/properlaw/intendedmeans separate; gameSEonlysensitivity,7weekclustersinsufficient.')
 write(root/'CATEGORY_COMPARISON.json',result)
 lines=['# D1/D2: executed opponent-information comparison','',
'The historical wave completed all672registered cells:556new fits/retained models and116explicit no-fit fallbacks. It reused the same17,968query identities across107games in2026Weeks1–7 and generated268,336retained prediction views, summarized by3,216canonical score views. Original controls were not refitted. The run took309.97wall/368.67CPU seconds, two threads and1,883,930,624bytes peak RSS, within the registered budget.','',
'D1adds four prior opponent-position qualified-population raw-total/coverage inputs. D2 keeps D1 and adds five matched-exposure shrunk-rate/deviation/support/age inputs. The original20own-history/position features,32-tree learner, fit origins, training members, exact priors and cold-start route stayed fixed. Adding features changes feature competition and random split behavior even under a fixed seed; this is a versioned information ablation, not a causal defensive-talent estimate or a new model family.','',
'## Native point results','',
'Numeric errors areMAE; TDprobabilities useBrier. Each row selects the best observed D1/D2 history/product after exposure to2026, and compares with the strongest preceding family representative. This is descriptive research selection, not an earlier-frozen next-week routing policy. Positive change is worse. All policies/products, extended populations, weeks, learned overlap, failures/fallbacks and adverse results remain in the canonical score artifact.','',
'| Target | n | Candidate group / policy / product | Error | Same-policy ordered control | Previous strongest | Change vs previous strongest |','| --- | ---: | --- | ---: | ---: | ---: | ---: |']
 for r in point:lines.append(f"| {r['target']} | {r['n']} | {r['information_group']} / {r['policy_id']} / {r['product_id']} | {r['candidate_error']:.6f} | {r['same_policy_ordered_error']:.6f} | {r['prior_strongest_error']:.6f} | {r['error_delta_vs_prior_strongest']:+.6f} |")
 lines+=['','## Proper distributions and genuine means','',
'CRPS is the predeclared proper law score for numeric targets, with PMFnegative-logloss, interval width/coverage and zero mass retained. TD usesBrier. These law/mean rows are views of fitted procedures, not additional learners. Count points from a Poisson fitting objective elsewhere are not assigned a PMF here.','',
'| Target | Best law group/policy | Law metric | Law error | Previous strongest | Change | Intended-mean MSE change vs previous strongest |','| --- | --- | --- | ---: | ---: | ---: | ---: |']
 for r in law:
  mr=next((x for x in mean if x['target']==r['target']),None);mc='—'if mr is None else f"{mr['error_delta']:+.6f}";lines.append(f"| {r['target']} | {r['information_group']} / {r['policy_id']} | {r['metric']} | {r['candidate_error']:.6f} | {r['prior_strongest_error']:.6f} | {r['error_delta']:+.6f} | {mc} |")
 lines+=['','Numeric startup laws can have impossible events and genuinely infinite log loss. CanonicalNLLnull with positiveinfinite_NLLcount meansINFINITE, never zero loss or successful missing evidence. Chart laws retain signed0.02support; median1/5/10point tolerances use exact integer coordinates. Genuine means are unrounded and ranked separately byMSE/RMSE. The35unknown current chart labels remain in forecast coverage.','',
'Defense summaries describe qualified observed-position rows, not complete official team totals. Missing target/appearance/exposure rows keep relevant group observations incomplete and consume the four-game window. A nonnull shrunk rate can be the earlier league prior alone when local support is absent; local exposure/game counts are explicit inputs and audits. Same-history feature memory is fixed across the three fitting-window arms; STRICTrestricts own/opponent/league information to2026but retains historically chosen architecture and retrospective query eligibility.','',
'Every primary canonical comparison pairs the exact same supported queries with the original same-policy ordered control and retains absolute/relative changes, game-cluster sensitivity and weekly differences. Seven exposed week clusters do not meet the registered eight-week interval threshold; sensitivity intervals do not correct selection or multiplicity. Strongest-reference uncertainty cannot be manufactured from aggregate errors.','',
'[Point minima](OBSERVED_POINT_MINIMA.csv) · [Proper-law minima](OBSERVED_PROPER_LAW_MINIMA.csv) · [Genuine means](OBSERVED_GENUINE_MEAN_MINIMA.csv) · [All full-policy comparisons](CATEGORY_COMPARISON.json) · [Canonical scores](SCORES.json) · [Historical receipt](HISTORICAL_RUN_RECEIPT.json) · [Protocol](FROZEN_PROTOCOL.json) · [Prior art/pathway gaps](PRIOR_ART_AND_PATHWAY_GAPS.md)','',
'Future Week8results remain unscored; any new shadow capture is separately recorded with actual issuance/persistence clocks, original00:27fit membership, new fixed query-information asof and all2229query cells across13remaining games. Production/owner integration remains unchanged.']
 (root/'EXECUTED_RESULTS.md').write_text('\n'.join(lines)+'\n');return dict(point_rows=len(point),proper_law_rows=len(law),mean_rows=len(mean),improved_point_categories=sum(r['error_delta_vs_prior_strongest']<-1e-12 for r in point),tied_point_categories=sum(abs(r['error_delta_vs_prior_strongest'])<=1e-12 for r in point))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--public-root',type=Path,required=True);p.add_argument('--leader-file',type=Path,required=True);print(json.dumps(run(**vars(p.parse_args()))))
